<script setup>
import { today, initials, money } from '#shared/utils/format.js'
const date=ref(today());const locationId=ref('');const {canManageOrders,canAssign,isLocationAdmin}=useAuth()
const query=computed(()=>({date:date.value,...(locationId.value?{locationId:locationId.value}:{})}))
const {data:orders,refresh,error}=await useOrders(query)
const {data:locations}=await useFetch(isLocationAdmin.value?'/api/orders/options':'/api/locations',{default:()=>[]})
const {data:therapists}=await useFetch('/api/therapists',{default:()=>[]})
const {data:schedules,refresh:refreshSchedules}=await useFetch(isLocationAdmin.value?'/api/therapists/schedules':'/api/schedules',{query:{date},default:()=>[]})
const waiting=computed(()=>orders.value.filter(o=>['NEW','CONFIRMED','ASSIGNED_LOCATION','THERAPIST_REJECTED','NO_THERAPIST_AVAILABLE','ASSIGNED_THERAPIST'].includes(o.orderStatus)))
const active=computed(()=>orders.value.filter(o=>['ACCEPTED','ON_THE_WAY','ARRIVED','IN_PROGRESS'].includes(o.orderStatus)))
const visibleTherapists=computed(()=>therapists.value.filter(t=>!locationId.value||t.locationIds.includes(Number(locationId.value))))
function availability(t){const job=orders.value.find(o=>o.assignment?.therapistId===t.id&&!['COMPLETED','PAID','CLOSED','CANCELLED_BY_ADMIN','CANCELLED_BY_CUSTOMER'].includes(o.orderStatus));const schedule=schedules.value.find(s=>s.therapistId===t.id);return job?'BOOKED':schedule?.status||'OFF'}
usePolling(async()=>{await refresh();await refreshSchedules()})
</script><template><div><LayoutPageHeader title="Dispatch board" description="Hubungkan setiap booking dengan tim yang tepat." eyebrow="LIVE OPERATIONS"><input v-model="date" type="date" aria-label="Tanggal dispatch" /><select v-model="locationId" aria-label="Lokasi dispatch"><option value="">Semua lokasi</option><option v-for="l in (isLocationAdmin?locations?.locations||[]:locations)" :key="l.id" :value="l.id">{{ l.name }}</option></select><UiButton v-if="canManageOrders" to="/orders/new"><UiIcon name="plus" :size="17" />Buat order</UiButton></LayoutPageHeader><p v-if="error" class="error-message">{{ error.data?.statusMessage }}</p><div class="dispatch-grid"><section><div class="section-title"><h2>Menunggu dispatch <span class="count">{{ waiting.length }}</span></h2><span class="muted">{{ date }}</span></div><div class="dispatch-cards"><div v-for="o in waiting" :key="o.id" class="panel dispatch-card"><div class="dispatch-card-top"><strong>{{ o.bookingTime.slice(0,5) }}</strong><UiBadge :status="o.orderStatus" /></div><p class="order-number">{{ o.orderNumber }}</p><h3>{{ o.customerName }}</h3><p>{{ o.items.map(i=>i.serviceNameSnapshot).join(', ') }} · {{ o.items.reduce((n,i)=>n+i.durationMinutes*i.qty,0) }} menit</p><div class="dispatch-address"><UiIcon name="locations" :size="16" /><span>{{ o.addressSnapshot }}</span></div><div class="dispatch-card-bottom"><span>{{ o.locationName || 'Belum ada lokasi' }}</span><UiButton :to="'/orders/'+o.id" variant="secondary">{{ o.orderStatus==='NEW'?'Konfirmasi':canAssign?'Atur assignment':'Atur lokasi' }}<UiIcon name="arrow" :size="15" /></UiButton></div></div></div><UiEmptyState v-if="!waiting.length" title="Dispatch terkendali" message="Semua booking sudah ditangani untuk tanggal ini." icon="success" /><div class="section-title mt-8"><h2>Job aktif <span class="count">{{ active.length }}</span></h2></div><NuxtLink v-for="o in active" :key="o.id" :to="'/orders/'+o.id" class="panel active-job-row"><span class="avatar pastel">{{ initials(o.assignment?.therapistName) }}</span><div><strong>{{ o.assignment?.therapistName }} → {{ o.customerName }}</strong><small>{{ o.bookingTime.slice(0,5) }} · {{ o.locationName }}</small></div><UiBadge :status="o.orderStatus" /><UiIcon name="right" :size="16" /></NuxtLink></section><aside class="panel availability-panel"><div class="panel-heading"><div><h2>Tim & availability</h2><p class="muted">Jadwal kerja dan booking harian</p></div><span class="live-dot" /></div><div v-for="t in visibleTherapists" :key="t.id" class="availability-row"><span class="avatar pastel">{{ initials(t.name) }}</span><div><strong>{{ t.name }}</strong><small>{{ t.locations.map(l=>l.name).join(', ') }}</small><small>{{ schedules.find(s=>s.therapistId===t.id)?.startTime.slice(0,5) || '—' }} – {{ schedules.find(s=>s.therapistId===t.id)?.endTime.slice(0,5) || '—' }}</small></div><UiBadge :status="availability(t)" /></div><div class="availability-note"><UiIcon name="users" :size="18" /><p>Saat assignment, sistem memeriksa slot waktu secara spesifik untuk mencegah double booking.</p></div></aside></div></div></template>